-- passengers: 96 registros fictícios.

-- responsibles: 64 registros fictícios.

-- passengers_responsibles: 96 registros fictícios.

-- routes: 8 registros fictícios.

-- route_stops: 64 pontos simulados de embarque e 8 destinos escolares fictícios.

-- route_passengers: 96 registros fictícios.

-- Alunos do mesmo endereço compartilham a parada da casa.
UPDATE `route_passengers` AS rp
JOIN `passengers` AS p ON p.`id` = rp.`passenger_id`
JOIN `route_stops` AS rs ON rs.`route_id` = rp.`route_id` AND rs.`address_id` = p.`addresses_id`
SET rp.`stop_id` = rs.`id`;

-- trips: 26 registros fictícios.

-- access_events: 468 registros fictícios.

-- vehicle_locations: 12 registros fictícios.

COMMIT;

-- Garante que o identificador usado pelos vínculos seja único em volumes antigos.
SET @responsible_id_unique_exists = (
  SELECT COUNT(*) FROM (
    SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS
    WHERE TABLE_SCHEMA = 'app_db' AND TABLE_NAME = 'responsibles' AND NON_UNIQUE = 0
    GROUP BY INDEX_NAME
    HAVING COUNT(*) = 1 AND MIN(COLUMN_NAME) = 'id'
  ) AS unique_responsible_id_indexes
);
SET @responsible_id_unique_migration = IF(@responsible_id_unique_exists = 0,
  'ALTER TABLE `app_db`.`responsibles` ADD UNIQUE INDEX `uq_responsibles_id` (`id`)',
  'SELECT 1');
PREPARE responsible_id_unique_statement FROM @responsible_id_unique_migration;
EXECUTE responsible_id_unique_statement;
DEALLOCATE PREPARE responsible_id_unique_statement;

-- Reajusta os próximos IDs após a carga concluída.

ALTER TABLE `vehicle_locations` AUTO_INCREMENT = 1;
